  function hazardState(z,m=method()){if(!z)return{risk:0,safety:100,collapse:0,gas:0,water:0};const depth=depthRatio(z),st=clamp(Number(S.mineStability[z.id]||0)),gas=clamp(Number(S.mineGas[z.id]||0)),water=clamp(Number(S.mineWater[z.id]||0)),support=infraEffect(z,'support'),vent=Number(z.naturalVentilation||0)+infraEffect(z,'ventilation'),drain=Number(z.naturalDrainage||0)+infraEffect(z,'drainage'),light=gearEffect('lightSafety'),protection=gearEffect('injuryReduction');let collapse=Number(z.collapseRisk||0)*(.30+depth*.80)*(1+(100-st)/80)-support*.16-infraEffect(z,'collapseReduction')*100;let gasRisk=Number(z.gasRisk||0)*(.25+depth*.75)+gas*.24-vent*.13-infraEffect(z,'gasReduction')*100;let waterRisk=Number(z.waterRisk||0)*(.25+depth*.75)+water*.22-drain*.13-infraEffect(z,'waterReduction')*100;let risk=Number(z.baseHazard||0)+collapse+gasRisk+waterRisk-light*.35-protection*.28+(m===METHODS.aggressive?8:m===METHODS.careful?-3:0)+(S.safetyPriority?-5:0)-careerEffect('safetyBonus');risk=clamp(risk,1,72);return{risk,safety:clamp(100-risk*1.25,10,99),collapse:clamp(collapse,0,100),gas:clamp(gasRisk,0,100),water:clamp(waterRisk,0,100),support,vent,drain,gasLevel:gas,waterLevel:water,stability:st,depth};}
