  function advanceGate(z,nextDepth){const req=advanceRequirements(z,nextDepth),vals={support:infraEffect(z,'support'),ventilation:Number(z.naturalVentilation||0)+infraEffect(z,'ventilation'),drainage:Number(z.naturalDrainage||0)+infraEffect(z,'drainage'),access:infraEffect(z,'access')};const missing=[];for(const k of Object.keys(req))if(vals[k]<req[k])missing.push(`${k==='support'?'soutènement':k==='ventilation'?'ventilation':k==='drainage'?'drainage':'accès'} ${Math.round(vals[k])}/${req[k]}`);return{ok:!missing.length,missing,req,vals};}
