  function reputationTiers(){return (C.content.miningReputationTiers||[]).filter(x=>!x.jobId||x.jobId==='miner').sort((a,b)=>Number(a.minReputation||0)-Number(b.minReputation||0));}function reputationTier(){const rep=Number(S.reputation||0);return reputationTiers().filter(t=>rep>=Number(t.minReputation||0)).pop()||reputationTiers()[0]||null;}function nextReputationTier(){const rep=Number(S.reputation||0);return reputationTiers().find(t=>rep<Number(t.minReputation||0))||null;}function sealDefs(){return (C.content.miningMasterySeals||[]).filter(x=>!x.jobId||x.jobId==='miner');}function masterCareer(){return C.miningMasterCareer?C.miningMasterCareer('miner'):(C.content.miningMasterCareers||[]).find(x=>x.jobId==='miner');}function sealUnlocked(id){return S.masterySeals.includes(id);}function reputationEffect(key){return Number(reputationTier()?.effects?.[key]||0);}function sealEffect(key){return sealDefs().filter(x=>sealUnlocked(x.id)).reduce((a,x)=>a+Number(x.effects?.[key]||0),0);}function masterEffect(key){return S.masterCertified?Number(masterCareer()?.effects?.[key]||0):0;}function careerEffect(key){return reputationEffect(key)+sealEffect(key)+masterEffect(key);}function endorsementThreshold(c){return Number(c?.endorsementTrust??40);}function hasEndorsement(id){return S.endorsements.includes(id);}function canRequestEndorsement(c){return !!c&&!c.masterOnly&&!hasEndorsement(c.id)&&rankOrder()>=4&&S.reputation>=55&&clientTrust(c.id)>=endorsementThreshold(c);}function completedContract(id){return S.contractHistory.some(h=>h.contractId===id&&h.status==='delivered');}function primaryCapstoneDone(){return !!S.specialization.primary&&spentInSpec(S.specialization.primary)>=4;}function safeDeepZoneCount(){return (C.content.mineZones||[]).filter(z=>workingDepth(z)>=Math.max(12,Number(z.depth||0)+5)&&hazardState(z).safety>=65).length;}
  function specDefs(){return C.content.miningSpecializations||[];}function specPointTotal(){return Math.max(0,Math.floor((S.level-3)/2));}function hasTalent(id){return !!S.specialization.talents[id];}function spentInSpec(id){const d=specDef(id);return d?(d.talents||[]).filter(t=>hasTalent(t.id)).reduce((a,t)=>a+Number(t.cost||1),0):0;}function specPointsSpent(){return specDefs().reduce((a,d)=>a+spentInSpec(d.id),0);}function specPointsFree(){return Math.max(0,specPointTotal()-specPointsSpent());}function activeSpec(id){return S.specialization.primary===id||S.specialization.secondary===id;}function specEffect(key){let n=0;for(const d of specDefs()){if(!activeSpec(d.id))continue;for(const t of d.talents||[])if(hasTalent(t.id))n+=Number(t.effects?.[key]||0);}return n;}function canInvestTalent(specId,t){return activeSpec(specId)&&!hasTalent(t.id)&&specPointsFree()>=Number(t.cost||1)&&(t.requires||[]).every(hasTalent);}
  function wearTool(phase,hardness=1,mult=1,toolId=''){const t=miningTool(toolId)||equippedTool(phase);if(!t||!ownsTool(t.id))return;let wear=Number(t.wear||1)*Math.max(.7,Number(hardness||1))*Math.max(.35,Number(mult||1));wear*=Math.max(.45,1+gearEffect('wear')+(Number(hardness||1)>=3?specEffect('hardRockWear')+careerEffect('hardRockWear'):0));S.toolCondition[t.id]=clamp(toolCondition(t.id)-wear,0,toolMax(t.id));if(S.toolCondition[t.id]<=0)log(`${t.name} est hors service : entretiens-le dans l’onglet Équipement.`);}
