  function siteRequirements(x){const rows=[],add=(label,have,need)=>rows.push({label,have,need,ok:Number(have)>=Number(need)});add('Niveau',S.level,x.minLevel||1);add('Grade',rankOrder(),x.minRank||0);add('Réputation',S.reputation,x.minReputation||0);add('Contrats réussis',S.completedContracts,x.minContracts||0);if(x.requiredZoneId&&Number(x.requiredDepth||0)>0)add(`Profondeur ${zone(x.requiredZoneId)?.name||x.requiredZoneId}`,workingDepth(zone(x.requiredZoneId)),x.requiredDepth);for(const id of x.requiresSites||[])rows.push({label:`Lieu ${mineSite(id)?.name||id}`,have:siteKnown(id)?1:0,need:1,ok:siteKnown(id)});return rows;}
