  window.minerDiscoverSite=id=>{const x=mineSite(id);if(!x||!canDiscoverSite(x))return;const duration=Math.max(5,Number(x.duration||15));S.tasks.push({id:uid(),type:'site',siteId:id,start:Date.now(),end:Date.now()+duration*1000,duration});log(`Reconnaissance lancée : ${x.name}.`);render();};
