  window.minerPuzzleAnswer=answer=>{const p=S.pendingPuzzle;if(!p)return;let ok=false;if(p.type==='fracture_sequence')ok=answer===p.payload.safe;else if(p.type==='support_choice')ok=answer===p.payload.best;else ok=answer===p.payload.best;S.stats.puzzles++;if(ok){S.stats.puzzlesWon++;C.gainJobXp('miner',10);C.gainMastery('miner',3);log(`Geste technique réussi : ${miningPuzzle(p.type)?.name||p.type}.`);}else log(`Geste technique imparfait : ${miningPuzzle(p.type)?.name||p.type}. Le lot ou la sécurité en souffre.`);const task=p.task,kind=p.kind;S.pendingPuzzle=null;renderMiningPuzzle();if(kind==='extract')finishExtract(task,{success:ok});else if(kind==='sort')finishSort(task,{success:ok});C.save();render();};
  function marketDemand(id){return clamp(Number(S.marketDemand[id]||1),.5,1.6);}function demandLabel(v){return v>=1.16?'Forte':v<=.88?'Faible':'Normale';}function demandClass(v){return v>=1.16?'high':v<=.88?'low':'normal';}function refreshMarket(force=false){const now=Date.now();if(!force&&now-S.lastMarketTick<180000)return false;for(const m of C.content.miningMarket||[]){const prev=marketDemand(m.id),pull=(1-prev)*.45,shock=(Math.random()-.5)*.24;S.marketDemand[m.id]=clamp(prev+pull+shock,Number(m.minDemand||.75),Number(m.maxDemand||1.35));}S.lastMarketTick=now;return true;}
  function marketItem(id){return C.miningMarketItem?C.miningMarketItem(id):(C.content.miningMarket||[]).find(x=>x.id===id);}function resourceSalePrice(id){const m=marketItem(id);return m?Math.max(1,Math.round(Number(m.basePrice||1)*marketDemand(id)*(1+gearEffect('saleTransport'))*(1+careerEffect('marketBonus')))):0;}
  function mineralLotPrice(id,lot){const m=marketItem(id);if(!m)return 0;const purity=.55+clamp(Number(lot.purity||50),0,100)/100*.75,quality=.72+clamp(Number(lot.quality||50),0,100)/100*.58;let mult=marketDemand(id)*(1+gearEffect('saleTransport'))*(1+careerEffect('marketBonus'));if(Number(lot.quality||0)>=72||Number(lot.purity||0)>=82)mult*=1+specEffect('premiumSale');return Math.max(1,Math.round(Number(m.basePrice||1)*Math.max(1,Number(lot.quantity||1))*purity*quality*mult));}
  function clampRep(n){return clamp(Number(n||0),0,100);}
  function minerClients(){return (C.content.jobClients||[]).filter(c=>c.jobId==='miner').sort((a,b)=>Number(a.minRank||0)-Number(b.minRank||0));}
  function minerContracts(){return (C.content.jobContracts||[]).filter(c=>c.jobId==='miner');}
