  function canPromote(){const next=C.nextProfessionalRank('miner');return !!next&&rankRequirements(next).every(r=>r.ok);}
  window.minerPromote=()=>{const next=C.nextProfessionalRank('miner');if(!next||!canPromote())return;C.promoteJob('miner');C.gainVillageXp(8+Number(next.order||0)*4);log(`Promotion validée : ${next.name}. Les nouveaux commanditaires et contrats de ce grade peuvent désormais apparaître.`);S.lastContractRefresh=0;C.save();render();};

  function contractEligible(def){if(!def)return false;const client=C.jobClient(def.clientId),masterOk=!def.requiresMaster||S.masterCertified,clientOk=!client||((!client.masterOnly||S.masterCertified)&&rankOrder()>=Number(client.minRank||0));return masterOk&&clientOk&&rankOrder()>=Number(def.minRank||0)&&S.level>=Number(def.minLevel||1)&&S.reputation>=Number(def.minReputation||0)&&clientTrust(def.clientId)>=Number(def.minTrust||0)&&(!def.requiredSite||siteKnown(def.requiredSite));}
