  function compatibleLots(def){const lots=C.state.materialLots?.[def?.resourceId];if(!Array.isArray(lots))return[];return lots.filter(l=>mineralLotCompatible(l,def));}
  function compatibleContractQty(def){if(!def)return 0;const lots=C.state.materialLots?.[def.resourceId];return Array.isArray(lots)?compatibleLots(def).reduce((n,l)=>n+Number(l.quantity||0),0):C.resource(def.resourceId);}
  function criteriaText(def){const c=mineralCriteria(def),bits=[];if((c.depositIds||[]).length)bits.push(`Gisement : ${(c.depositIds||[]).map(id=>dep(id)?.name||id).join(' / ')}`);if(Number(c.purityMin||0)>0)bits.push(`Pureté ≥ ${c.purityMin}%`);if(Number(c.qualityMin||0)>0)bits.push(`Qualité ≥ ${qualityName(c.qualityMin)}`);return bits.join(' · ')||'Aucun critère qualitatif';}
  function consumeCompatible(def,qty){let remaining=Math.max(0,Number(qty||0)),puritySum=0,qualitySum=0,used=0;const lots=C.state.materialLots?.[def.resourceId];if(!Array.isArray(lots)){if(!C.consumeResource(def.resourceId,remaining))return null;return{avgPurity:0,avgQuality:0};}for(const l of lots){if(remaining<=0)break;if(!mineralLotCompatible(l,def))continue;const take=Math.min(remaining,Number(l.quantity||0));l.quantity-=take;remaining-=take;used+=take;puritySum+=take*Number(l.purity||0);qualitySum+=take*Number(l.quality||0);}if(remaining>0)return null;C.state.materialLots[def.resourceId]=lots.filter(l=>Number(l.quantity||0)>0);C.state.resources[def.resourceId]=Math.max(0,C.resource(def.resourceId)-Number(qty||0));C.recordInventoryEvent('out',def.resourceId,qty,'Livraison contrat Mineur');return{avgPurity:used?puritySum/used:0,avgQuality:used?qualitySum/used:0};}
