  function activeContractLimit(){return Math.max(3,3+Math.round(careerEffect('activeContractSlots')));}
  function cleanupOffers(){const now=Date.now();S.contractOffers=S.contractOffers.filter(o=>Number(o.expiresAt||0)>now);}
  function generateContractOffers(force=false){cleanupOffers();const now=Date.now();if(!force&&now-Number(S.lastContractRefresh||0)<12000)return;S.lastContractRefresh=now;const occupied=new Set([...S.contractOffers,...S.activeContracts].map(x=>x.contractId)),pool=minerContracts().filter(d=>contractEligible(d)&&!occupied.has(d.id));for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}while(S.contractOffers.length<4&&pool.length){const d=pool.shift();S.contractOffers.push({id:uid(),contractId:d.id,createdAt:now,expiresAt:now+90000});}}
  function failContract(active,reason='Délai dépassé'){const d=C.jobContract(active.contractId);if(!d)return;const f=d.failure||{};S.reputation=clampRep(S.reputation-Number(f.reputation||0));S.clientTrust[d.clientId]=clampRep(clientTrust(d.clientId)-Number(f.trust||0));S.failedContracts++;S.contractHistory.unshift({contractId:d.id,status:'failed',at:Date.now(),reason});S.contractHistory=S.contractHistory.slice(0,50);log(`Contrat échoué — ${d.name}. ${reason}.`);}
  function contractTick(){cleanupOffers();const now=Date.now(),expired=S.activeContracts.filter(a=>Number(a.end||0)<=now);if(expired.length){for(const a of expired)failContract(a);const gone=new Set(expired.map(a=>a.id));S.activeContracts=S.activeContracts.filter(a=>!gone.has(a.id));S.lastContractRefresh=0;}generateContractOffers();}
  window.minerAcceptContract=id=>{const o=S.contractOffers.find(x=>x.id===id),d=C.jobContract(o?.contractId);if(!o||!d||!contractEligible(d)||S.activeContracts.length>=activeContractLimit())return;S.contractOffers=S.contractOffers.filter(x=>x.id!==id);S.activeContracts.push({id:uid(),contractId:d.id,acceptedAt:Date.now(),end:Date.now()+Number(d.duration||180)*1000});log(`Contrat accepté : ${d.name}.`);C.save();render();};
