  window.minerDeliverContract=id=>{const a=S.activeContracts.find(x=>x.id===id),d=C.jobContract(a?.contractId);if(!a||!d||compatibleContractQty(d)<Number(d.quantity||1))return;const delivered=consumeCompatible(d,Number(d.quantity||1));if(!delivered)return;const remarkable=contractRemarkable(d,delivered),bonus=remarkable?1.2+specEffect('remarkableBonus'):1,reward=d.reward||{},renownTreasury=Math.max(0,Math.round(Number(reward.treasury||0)*careerEffect('contractReward'))),trustGain=Math.max(0,Math.round((Number(reward.trust||0)+(remarkable?1:0))*(1+careerEffect('trustGain'))));C.gainJobXp('miner',Math.round(Number(reward.jobXp||0)*bonus));C.gainVillageXp(Math.round(Number(reward.villageXp||0)*bonus));C.gainMastery('miner',remarkable?4:2);S.reputation=clampRep(S.reputation+Number(reward.reputation||0)+(remarkable?2:0));S.clientTrust[d.clientId]=clampRep(clientTrust(d.clientId)+trustGain);C.state.treasury=Math.max(0,Number(C.state.treasury||0)+Math.round(Number(reward.treasury||0)*bonus)+renownTreasury);S.completedContracts++;if(d.requiredSite||Number(d.minRank||0)>=4)S.stats.prestigeContracts++;if(d.requiresMaster)S.stats.masterContracts++;if(remarkable)S.stats.remarkableContracts++;S.contractHistory.unshift({contractId:d.id,status:'delivered',at:Date.now(),remarkable,avgPurity:delivered.avgPurity,avgQuality:delivered.avgQuality});S.contractHistory=S.contractHistory.slice(0,50);S.activeContracts=S.activeContracts.filter(x=>x.id!==id);S.lastContractRefresh=0;log(`${remarkable?'Livraison remarquable':'Contrat livré'} : ${d.name}. Réputation ${Math.round(S.reputation)}/100.${renownTreasury?` Prime de renommée +${renownTreasury} couronnes.`:''}`);C.save();render();};
  window.minerBuyTool=id=>{const t=miningTool(id);if(!t||ownsTool(id)||!meetsGate(t))return;const price=Math.max(0,Number(t.price||0));if(Number(C.state.treasury||0)<price)return alert(`Il faut ${price} couronnes dans la trésorerie.`);C.state.treasury-=price;S.ownedTools.push(id);S.toolCondition[id]=toolMax(id);if(!S.equippedTools[t.operation])S.equippedTools[t.operation]=id;S.stats.toolsBought++;log(`Outil acheté : ${t.name} pour ${price} couronnes.`);C.save();render();};
  window.minerEquipTool=id=>{if(S.tasks.length)return alert('Termine d’abord l’action en cours avant de changer d’outil.');const t=miningTool(id);if(!t||!ownsTool(id)||!meetsGate(t))return;S.equippedTools[t.operation]=id;log(`${t.name} équipé pour ${t.operation==='prospect'?'la prospection':t.operation==='extract'?'l’extraction':'le tri'}.`);C.save();render();};
  window.minerRepairTool=id=>{if(S.tasks.length)return alert('Termine d’abord l’action en cours avant d’entretenir un outil.');const t=miningTool(id);if(!t||!ownsTool(id)||toolCondition(id)>=toolMax(id)-.5)return;const cost=repairCost(id);if(cost<=0&&t.starter&&toolCondition(id)<=0){S.toolCondition[id]=Math.round(toolMax(id)*.25);log(`Remise en état de secours : ${t.name} revient à 25 %. `);}else{if(Number(C.state.treasury||0)<cost)return alert(`Il faut ${cost} couronne${cost>1?'s':''}.`);C.state.treasury-=cost;S.toolCondition[id]=toolMax(id);S.stats.repairs++;log(`${t.name} entretenu pour ${cost} couronne${cost>1?'s':''}.`);}C.save();render();};
  window.minerBuyGear=id=>{const g=miningGear(id);if(!g||ownsGear(id)||!meetsGate(g))return;const price=Math.max(0,Number(g.price||0));if(Number(C.state.treasury||0)<price)return alert(`Il faut ${price} couronnes.`);C.state.treasury-=price;S.ownedGear.push(id);if(!S.equippedGear[g.slot])S.equippedGear[g.slot]=id;S.stats.toolsBought++;log(`Équipement acheté : ${g.name}.`);C.save();render();};
  window.minerEquipGear=id=>{if(S.tasks.length)return alert('Termine d’abord l’action en cours avant de changer d’équipement.');const g=miningGear(id);if(!g||!ownsGear(id)||!meetsGate(g))return;S.equippedGear[g.slot]=id;log(`${g.name} équipé.`);C.save();render();};
