  function commitActiveMineGesture(v,performance){const p=S.currentProspect;if(!v||!p||S.tasks.length||yardCount()>=yardCapacity())return;const {z,d,g,tool,fatigue,reserve,reserveCost,stabilityDamage,hz}=v;if(S.energy<fatigue||reserve<reserveCost)return;S.energy=clamp(S.energy-fatigue);S.mineReserve[z.id]=clamp(reserve-reserveCost,0,Number(z.reserveMax||100));S.mineStability[z.id]=clamp(Number(S.mineStability[z.id]||0)-stabilityDamage,0,100);const duration=Math.max(2,Number(v.duration||4)*Number(performance.durationMult||1)),now=Date.now();S.tasks.push({id:uid(),type:'extract',zoneId:z.id,depositId:d.id,depth:workingDepth(z),methodId:$('#mineMethodSelect').value,gestureId:g?.id||'',toolId:tool.id,prospect:{...p},hazardRisk:hz.risk,start:now,end:now+duration*1000,duration,activeMine:performance});p.usesLeft=Math.max(0,Number(p.usesLeft||0)-1);if(p.rareId)p.rareId='';S.stats.extractions++;if(workingDepth(z)>=15&&hazardState(z).safety>=65)S.stats.safeDeepExtractions++;S.stats.deposits[d.id].extractions++;log(`Geste ${performance.grade} : extraction engagée sur ${d.name} · ${Math.round(duration*10)/10}s · précision ${performance.distance} · ${performance.misses} reprise${performance.misses>1?'s':''}.`);C.save();render();triggerWorkshopActionPulse();}
