  function recordIncident(z,type,severity,message){S.stats.incidents++;if(severity==='serious')S.stats.seriousIncidents++;S.mineIncidents.unshift({id:uid(),zoneId:z.id,type,severity,message,depth:workingDepth(z),at:Date.now()});S.mineIncidents=S.mineIncidents.slice(0,40);log(`⚠️ ${message}`);}
