    if(type==='water'){const add=15+Math.random()*18;S.mineWater[z.id]=clamp(Number(S.mineWater[z.id]||0)+add,0,100);S.mineStability[z.id]=clamp(Number(S.mineStability[z.id]||0)-3,0,100);recordIncident(z,'water',S.mineWater[z.id]>72?'serious':'minor',`Venue d’eau : niveau d’humidité du chantier porté à ${Math.round(S.mineWater[z.id])}%. Le drainage devient prioritaire.`);return{yieldMult:.92,qualityPenalty:3};}
    S.mineStability[z.id]=clamp(Number(S.mineStability[z.id]||0)-5,0,100);recordIncident(z,'loose','minor','Plaque instable purgée tardivement : arrêt bref et perte de quelques fragments.');return{yieldMult:.93,qualityPenalty:3};
