  function scaledInstallationCost(inst,z){const next=infraLevel(z,inst.type)+1,mult=next;const out={};for(const [k,v] of Object.entries(inst.cost||{}))out[k]=Math.max(0,Math.ceil(Number(v||0)*mult));return out;}
  function costText(cost){return Object.entries(cost||{}).filter(([,v])=>Number(v)>0).map(([id,v])=>id==='treasury'?`${v} 🪙`:`${resourceDef(id)?.icon||'📦'} ${v} ${resourceDef(id)?.name||id}`).join(' · ')||'Sans coût';}
  function canPayCost(cost){for(const [id,v] of Object.entries(cost||{})){if(id==='treasury'){if(Number(C.state.treasury||0)<Number(v||0))return false;}else if(C.resource(id)<Number(v||0))return false;}return true;}
  function payCost(cost){if(!canPayCost(cost))return false;for(const [id,v] of Object.entries(cost||{})){if(id==='treasury')C.state.treasury-=Number(v||0);else C.consumeResource(id,Number(v||0));}return true;}
  window.minerUpgradeInfrastructure=id=>{const {z}=selected(),inst=mineInstallation(id);if(!z||!inst||S.tasks.length||!meetsGate(inst))return;const lvl=infraLevel(z,inst.type);if(lvl>=Number(inst.maxLevel||4))return;const cost=scaledInstallationCost(inst,z);if(!canPayCost(cost))return alert(`Matériaux insuffisants : ${costText(cost)}.`);const energy=4+lvl*2;if(S.energy<energy)return alert(`Il faut ${energy} énergie.`);if(!payCost(cost))return;S.energy=clamp(S.energy-energy);const duration=Math.max(3,Number(inst.baseDuration||8)*(1+lvl*.18));S.tasks.push({id:uid(),type:'infrastructure',zoneId:z.id,installationId:inst.id,start:Date.now(),end:Date.now()+duration*1000,duration});log(`Travaux lancés : ${inst.name} niveau ${lvl+1} dans ${z.name}.`);render();};
  function completeInfrastructure(t){const z=zone(t.zoneId),inst=mineInstallation(t.installationId);if(!z||!inst)return;const lvl=Math.min(Number(inst.maxLevel||4),infraLevel(z,inst.type)+1);S.mineInfrastructure[z.id][inst.type]=lvl;S.stats.infrastructureBuilt++;S.mineStability[z.id]=clamp(Number(S.mineStability[z.id]||0)+(inst.type==='support'?6:2),0,Number(z.stabilityBase||95));if(inst.type==='ventilation')S.mineGas[z.id]=clamp(Number(S.mineGas[z.id]||0)-18,0,100);if(inst.type==='drainage')S.mineWater[z.id]=clamp(Number(S.mineWater[z.id]||0)-18,0,100);C.gainJobXp('miner',8+lvl*4);C.gainVillageXp(3+lvl);log(`${inst.name} porté au niveau ${lvl} dans ${z.name}.`);}
  function startAdvanceMine(){const {z}=selected();if(!z||S.tasks.length||!accessibleZone(z))return;const current=workingDepth(z),max=Number(z.maxDepth??z.depth??0);if(current>=max-.01)return;const next=Math.min(max,current+Number(z.advanceStep||2)),gate=advanceGate(z,next),hz=hazardState(z);if(!gate.ok)return alert(`L’avancement exige d’abord : ${gate.missing.join(', ')}.`);if(hz.safety<35)return alert('La sécurité du chantier est trop faible pour ouvrir un nouveau front. Renforce d’abord l’infrastructure.');const energy=Math.max(4,Number(z.advanceEnergy||8)+Math.floor(depthRatio(z)*4));if(S.energy<energy)return alert(`Il faut ${energy} énergie.`);S.energy=clamp(S.energy-energy);const speed=Math.max(.55,1-infraEffect(z,'advanceSpeed')),duration=Math.max(4,Number(z.advanceDuration||10)*speed*(S.safetyPriority?1.12:1));S.tasks.push({id:uid(),type:'advance',zoneId:z.id,fromDepth:current,toDepth:next,hazardRisk:hz.risk,start:Date.now(),end:Date.now()+duration*1000,duration});log(`Avancement du front : ${z.name}, de ${Math.round(current)} à ${Math.round(next)} m.`);render();}
  function completeAdvance(t){const z=zone(t.zoneId);if(!z)return;S.mineDepth[z.id]=Math.min(Number(z.maxDepth??t.toDepth),Number(t.toDepth));S.currentProspect=null;S.mineReserve[z.id]=clamp(Math.max(Number(S.mineReserve[z.id]||0),Math.min(Number(z.reserveMax||100),58+depthRatio(z)*20)),0,Number(z.reserveMax||100));S.mineStability[z.id]=clamp(Number(S.mineStability[z.id]||0)-(3+depthRatio(z)*4)*(S.safetyPriority?.7:1),0,100);S.mineGas[z.id]=clamp(Number(S.mineGas[z.id]||0)+Number(z.gasRisk||0)*.08*(1+depthRatio(z)),0,100);S.mineWater[z.id]=clamp(Number(S.mineWater[z.id]||0)+Number(z.waterRisk||0)*.07*(1+depthRatio(z)),0,100);S.stats.advances++;C.gainJobXp('miner',10+Math.round(Number(t.toDepth)-Number(t.fromDepth))*2);C.gainMastery('miner',2);log(`Nouveau front ouvert à ${Math.round(S.mineDepth[z.id])} m dans ${z.name}. Les relevés précédents ne sont plus valables.`);if(Math.random()*100<Number(t.hazardRisk||0)*.45)resolveMiningIncident(z,METHODS.standard,equippedTool('extract'),Number(t.hazardRisk||0)*.6);}
  window.minerAdvanceMine=startAdvanceMine;
  window.minerToggleSafety=()=>{S.safetyPriority=!S.safetyPriority;log(`Priorité sécurité ${S.safetyPriority?'activée':'désactivée'} : ${S.safetyPriority?'travail plus lent, incidents et dommages réduits':'cadence normale rétablie'}.`);C.save();render();};

  function renderTimers(){const t=S.tasks[0];if(!t){$('#mineTimers').innerHTML='<div class="empty-state"><b>Aucun travail en cours</b><span>Prospecte, extrais, sécurise ou avance un front.</span></div>';return;}const left=Math.max(0,(t.end-Date.now())/1000),pct=clamp((1-left/Math.max(.1,t.duration))*100),labels={prospect:['🔎','Prospection du front'],extract:['⛏️','Extraction'],sort:['🧺','Tri du lot'],rest:['☕','Récupération'],advance:['🕳️','Avancement de la galerie'],infrastructure:['🏗️','Travaux de sécurisation'],site:['🧭','Reconnaissance d’un lieu unique']},[icon,label]=labels[t.type]||['⏳','Travail'],g=gesture(t.gestureId);$('#mineTimers').innerHTML=`<div class="task-card mine-task"><div class="task-icon">${icon}</div><div class="task-main"><b>${label}${g?` · ${esc(g.name)}`:''}</b><span>${left.toFixed(1)} s restantes</span><div class="progress"><i style="width:${pct}%"></i></div></div></div>`;}
  function renderStock(){const ids=['stone','clay','iron_ore','silver_ore','rock_crystal','mine_waste'];const rows=ids.map(id=>{const r=resourceDef(id),camp=id==='mine_waste'?localWaste():localMineralQty(id),warehouse=C.resource(id),total=camp+warehouse;return `<article class="mine-location-resource"><div class="mine-location-resource-head"><span>${r?.icon||'📦'}</span><div><b>${esc(r?.name||id)}</b><small>Total possédé : ${Math.floor(total)}</small></div></div><div class="mine-location-counts"><div><span>⛺ Camp du Mineur</span><b>${Math.floor(camp)}</b></div><div><span>📦 Entrepôt communal</span><b>${Math.floor(warehouse)}</b></div></div></article>`;}).join('');const lotRows=S.localMineralLots.length?S.localMineralLots.map(l=>{const r=resourceDef(l.resourceId),d=dep(l.depositId),market=marketItem(l.resourceId);return `<div class="mine-local-lot-row"><div><b>${r?.icon||'📦'} ${esc(r?.name||l.resourceId)}</b><small>${esc(d?.name||'Gisement')} · ${Math.round(Number(l.depth||0))} m · pureté ${Math.round(Number(l.purity||0))}% · ${qualityName(l.quality)}</small></div><strong>${Math.floor(Number(l.quantity||0))}</strong><div class="local-stock-safety-actions"><button class="btn" onclick="minerTransferLocalMineralLot('${l.id}')">📦 Entrepôt</button>${market?`<button class="btn" onclick="minerSellLocalMineralLot('${l.id}')">🪙 Vendre</button>`:''}<button class="btn danger" onclick="minerDiscardLocalMineralLot('${l.id}')">🗑️ Écarter</button></div></div>`;}).join(''):'<div class="empty-state compact"><b>Aucun lot préparé au camp</b><span>Les lots triés et stockés apparaîtront ici avant leur transfert communal.</span></div>';const wasteActions=localWaste()>0?`<div class="mine-waste-transfer"><button class="btn" onclick="minerTransferLocalWaste()">📦 Transférer ${Math.floor(localWaste())} stérile(s)</button><button class="btn danger" onclick="minerDiscardLocalWaste(true)">🗑️ Évacuer les stériles</button></div>`:'';$('#mineStock').innerHTML=`<div class="mine-location-intro"><div><b>⛺ Camp du Mineur</b><span>Ressources préparées mais encore réservées au métier.</span></div><div><b>📦 Entrepôt communal</b><span>Ressources disponibles pour tout le village.</span></div></div><div class="notice subtle"><b>Anti-blocage :</b> si l’Entrepôt est saturé, les lots restent au camp. Tu peux toujours les <strong>vendre</strong> ou les <strong>écarter</strong>. Les lots du front peuvent eux aussi être écartés.</div><div class="mine-location-resource-grid">${rows}</div><div class="mine-local-transfer-head"><div><b>Lots en attente au camp</b><small>Transfère-les pour les rendre accessibles aux autres métiers.</small></div><button class="btn primary" onclick="minerTransferAllLocal()" ${localMineTotal()<=0?'disabled':''}>Tout transférer</button></div><div class="mine-local-lot-list">${lotRows}</div>${wasteActions}`;}
  function renderLog(){$('#mineLog').innerHTML=S.logs.length?S.logs.slice(0,18).map(x=>`<div><span class="muted">${new Date(x.t).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}</span> ${esc(x.m)}</div>`).join(''):'<div class="muted">Le registre est encore vierge.</div>';}
  function rawLotCard(l){const d=dep(l.depositId),z=zone(l.zoneId),r=resourceDef(l.resourceId),sk=skillLevel('sorting'),g=selectedGesture('sort'),tool=equippedTool('sort'),k=knowledgeLevel(l.depositId),recovery=Math.min(.34,(sk-1)*.012+k*.01+gestureEffect(g,'recovery')+Number(tool?.recoveryBonus||0)+specEffect('recovery')),expected=Math.max(1,Math.round(l.quantity*(l.purity+(100-l.purity)*recovery)/100));return `<article class="mine-lot raw"><div class="mine-lot-head"><span>${d?.icon||'⛏️'}</span><div><b>${esc(d?.name||l.depositId)}</b><small>${esc(z?.name||'Zone')} · ${Math.round(Number(l.depth||0))} m · ${r?.name||l.resourceId}</small></div><strong>${l.quantity} brut</strong></div><div class="mine-lot-grid"><span>Pureté du lot <b>${Math.round(l.purity)}%</b></span><span>Qualité <b>${qualityName(l.quality)}</b></span><span>Utile attendu avec ce tri <b>≈ ${expected}</b></span><span>Outil <b>${esc(tool?.name||'Aucun')} · ${tool?.id?Math.round(toolConditionPct(tool.id)):0}%</b></span></div><div class="mine-lot-actions"><button class="btn primary" onclick="minerSortLot('${l.id}')" ${S.tasks.length||S.energy<(3+gestureEnergy(g))||!gestureUnlocked(g,d)||!tool||toolCondition(tool.id)<=0?'disabled':''}>🧺 Trier · ${g?.name||'Tri'} </button><button class="btn danger" onclick="minerDiscardRawLot('${l.id}')">🗑️ Écarter</button></div></article>`;}
  function sortedLotCard(l){const d=dep(l.depositId),r=resourceDef(l.resourceId);return `<article class="mine-lot sorted"><div class="mine-lot-head"><span>${r?.icon||'📦'}</span><div><b>${esc(r?.name||l.resourceId)}</b><small>Issu de ${esc(d?.name||l.depositId)} · ${Math.round(Number(l.depth||0))} m</small></div><strong>${l.quantity} utile${l.quantity>1?'s':''}</strong></div><div class="mine-lot-grid"><span>Pureté <b>${Math.round(l.purity)}%</b></span><span>Qualité <b>${qualityName(l.quality)}</b></span><span>Stériles séparés <b>${l.waste}</b></span><span>Tri <b>${esc(gesture(l.sortGestureId)?.name||'Standard')}</b></span></div><div class="mine-lot-actions"><button class="btn primary" onclick="minerStoreLot('${l.id}')" ${S.tasks.length?'disabled':''}>📦 Stocker le lot</button><button class="btn danger" onclick="minerDiscardSortedLot('${l.id}')">🗑️ Écarter</button></div></article>`;}
  function discardRawLot(id){const lot=S.rawLots.find(x=>x.id===id);if(!lot)return;if(!confirm('Écarter ce lot brut du front de taille ?'))return;S.rawLots=S.rawLots.filter(x=>x.id!==id);log(`🗑️ Lot brut de ${dep(lot.depositId)?.name||lot.depositId} écarté du front.`);C.save();render();}
