    $('#mineKnowledgeSummary').innerHTML=`<div class="knowledge-summary"><div><span>Gisements maîtrisés</span><b>${masteryCount}/${(C.content.mineralDeposits||[]).length}</b></div><div><span>Maîtrise métier</span><b>${C.masteryLevel('miner')}/10</b></div><div><span>Gestes pratiqués</span><b>${Object.values(S.stats.gestures||{}).filter(n=>n>0).length}/${(C.content.miningGestures||[]).length}</b></div></div>`;
