    $('#mineGestureCards').innerHTML=`<div class="mine-gesture-grid">${(C.content.miningGestures||[]).map(g=>{const m=gestureMastery(g.id),next=gestureNext(g.id),unlocked=gestureUnlocked(g),uses=S.stats.gestures[g.id]||0,skill=SKILLS[g.skill];return `<article class="mine-gesture-card ${unlocked?'open':'locked'}"><div class="gesture-title"><span>${g.icon||'🛠️'}</span><div><b>${esc(g.name)}</b><small>${g.phase==='prospect'?'Prospection':g.phase==='extract'?'Extraction':'Tri'} · ${skill?.name||g.skill}</small></div><strong>${unlocked?`M${m}/5`:'🔒'}</strong></div><p>${esc(g.description||'')}</p><div class="gesture-meta"><span>Requis : niv. ${g.minLevel} · ${skill?.name||g.skill} ${g.minSkill}</span><span>Pratiqué ${uses} fois</span><span>${next===null?'Maîtrise maximale':`${Math.floor(S.gestureXp[g.id]||0)} / ${next} XP de geste`}</span></div></article>`;}).join('')}</div>`;
    $('#mineSkillCards').innerHTML=`<div class="mine-skill-grid">${Object.entries(SKILLS).map(([key,def])=>{const lvl=skillLevel(key),xp=Number(S.skillXp[key]||0),next=skillNext(key),base=SKILL_THRESHOLDS[Math.max(0,lvl-1)],pct=next===null?100:clamp((xp-base)/(next-base)*100),effect=key==='prospecting'?`Relevés plus précis, davantage de passes et prospection plus rapide.`:key==='extraction'?`Extraction plus rapide, moins fatigante, rendement et qualité légèrement supérieurs.`:`Tri plus rapide et récupération accrue de matière utile.`;return `<article class="mine-skill-card"><div><span>${def.icon}</span><div><b>${def.name}</b><small>Niveau technique ${lvl}/10</small></div><strong>${Math.floor(xp)} XP</strong></div><div class="progress"><i style="width:${pct}%"></i></div><p>${effect}</p></article>`;}).join('')}</div>`;
